/*
Debug V1.0
Alias Name: debug
Alias Pattern: debug
Script Type: JavaScript Alias

Required Alias(s):
- none

Required Trigger(s):
- none

Optional Alias(s)/Trigger(s):
- gloot
- ginv
- gtrack
- ghunt
- quest
- ka
- restore
- package

Commands:
- debug
- debug list
- debug <module>
- debug <module> on
- debug <module> off
- debug all off
*/

(function () {
  "use strict";

  var VERSION = "Debug V1.0";
  var STORAGE_KEY = "genesisDebug";
  var MODULES = ["gloot", "ginv", "gtrack", "ghunt", "quest", "ka", "restore", "package"];

  // ---------- Output helpers ----------
  function echo(message, color) {
    if (window.gwc && gwc.output && typeof gwc.output.append === "function") {
      if (color) {
        gwc.output.append(String(message), color);
      } else {
        gwc.output.append(String(message));
      }
      return;
    }

    if (window.console && console.log) {
      console.log(String(message));
    }
  }

  function safeLower(value) {
    return String(value || "").trim().toLowerCase();
  }

  function normalizeModule(moduleName) {
    return safeLower(moduleName);
  }

  function isKnownModule(moduleName) {
    var mod = normalizeModule(moduleName);
    return MODULES.indexOf(mod) !== -1;
  }

  // ---------- Storage helpers ----------
  function ensureUserdata() {
    if (!window.gwc) window.gwc = {};
    if (!gwc.userdata) gwc.userdata = {};
    if (!gwc.userdata[STORAGE_KEY] || typeof gwc.userdata[STORAGE_KEY] !== "object") {
      gwc.userdata[STORAGE_KEY] = {};
    }
    return gwc.userdata[STORAGE_KEY];
  }

  function getDebugStore() {
    var store = ensureUserdata();
    var i;

    for (i = 0; i < MODULES.length; i += 1) {
      if (typeof store[MODULES[i]] !== "boolean") {
        store[MODULES[i]] = false;
      }
    }

    return store;
  }

  function setModule(moduleName, enabled) {
    var store = getDebugStore();
    var mod = normalizeModule(moduleName);

    if (!isKnownModule(mod)) {
      return false;
    }

    store[mod] = !!enabled;
    return true;
  }

  function toggleModule(moduleName) {
    var store = getDebugStore();
    var mod = normalizeModule(moduleName);

    if (!isKnownModule(mod)) {
      return null;
    }

    store[mod] = !store[mod];
    return store[mod];
  }

  function enabledModules() {
    var store = getDebugStore();
    var enabled = [];
    var i;

    for (i = 0; i < MODULES.length; i += 1) {
      if (store[MODULES[i]]) {
        enabled.push(MODULES[i]);
      }
    }

    return enabled;
  }

  // ---------- Public helper used by other scripts ----------
  window.GenesisDebug = {
    version: VERSION,

    modules: MODULES.slice(),

    enabled: function (moduleName) {
      var store = getDebugStore();
      var mod = normalizeModule(moduleName);

      if (!isKnownModule(mod)) {
        return false;
      }

      return !!store[mod];
    },

    log: function (moduleName, message, color) {
      var mod = normalizeModule(moduleName);

      if (!this.enabled(mod)) {
        return;
      }

      echo("[" + VERSION + "][" + mod + "] " + String(message), color || "#9ccfff");
    },

    set: function (moduleName, state) {
      return setModule(moduleName, state);
    },

    toggle: function (moduleName) {
      return toggleModule(moduleName);
    },

    list: function () {
      return enabledModules();
    }
  };

  // ---------- Alias argument parsing ----------
  function getRawInput() {
    if (typeof args === "undefined") {
      return "";
    }

    if (typeof args[0] === "string") {
      return args[0];
    }

    if (typeof args["*"] === "string") {
      return args["*"];
    }

    return "";
  }

  function getParts() {
    var raw = getRawInput();
    var parts;

    raw = String(raw || "").trim();

    if (!raw) {
      return [];
    }

    parts = raw.split(/\s+/);

    if (parts.length && safeLower(parts[0]) === "debug") {
      parts.shift();
    }

    return parts;
  }

  // ---------- Display ----------
  function statusLine(moduleName) {
    var store = getDebugStore();
    var padded = (moduleName + "        ").slice(0, 8);
    return "  " + padded + (store[moduleName] ? "ON" : "OFF");
  }

  function showHelp() {
    var lines = [];
    var i;

    lines.push("[" + VERSION + "]");
    lines.push("Debug modules: " + MODULES.join(", "));
    lines.push("");
    lines.push("Status:");

    for (i = 0; i < MODULES.length; i += 1) {
      lines.push(statusLine(MODULES[i]));
    }

    lines.push("");
    lines.push("Commands:");
    lines.push("  debug                  Show command list and enabled modules");
    lines.push("  debug list             Show enabled debug modules");
    lines.push("  debug <module>         Toggle debug for module");
    lines.push("  debug <module> on      Enable debug for module");
    lines.push("  debug <module> off     Disable debug for module");
    lines.push("  debug all off          Disable all debug output");

    echo(lines.join("\n"), "#B3EBF2");
  }

  function showEnabledList() {
    var enabled = enabledModules();

    if (!enabled.length) {
      echo("[" + VERSION + "] No debug modules are enabled.", "#B3EBF2");
      return;
    }

    echo("[" + VERSION + "] Enabled debug modules: " + enabled.join(", "), "#B3EBF2");
  }

  function showUnknownModule(moduleName) {
    echo("[" + VERSION + "] Unknown debug module: " + String(moduleName || ""), "red");
    echo("Known modules: " + MODULES.join(", "), "#B3EBF2");
  }

  function turnAllOff() {
    var i;

    for (i = 0; i < MODULES.length; i += 1) {
      setModule(MODULES[i], false);
    }

    echo("[" + VERSION + "] All debug output disabled.", "#B3EBF2");
  }

  // ---------- Main command handling ----------
  function main() {
    var parts = getParts();
    var moduleName;
    var action;
    var toggled;

    getDebugStore();

    if (!parts.length) {
      showHelp();
      return;
    }

    if (safeLower(parts[0]) === "list") {
      showEnabledList();
      return;
    }

    if (safeLower(parts[0]) === "all" && safeLower(parts[1]) === "off") {
      turnAllOff();
      return;
    }

    moduleName = normalizeModule(parts[0]);
    action = safeLower(parts[1]);

    if (!isKnownModule(moduleName)) {
      showUnknownModule(parts[0]);
      return;
    }

    if (!action) {
      toggled = toggleModule(moduleName);
      echo("[" + VERSION + "] Debug for " + moduleName + ": " + (toggled ? "ON" : "OFF"), "#B3EBF2");
      return;
    }

    if (action === "on") {
      setModule(moduleName, true);
      echo("[" + VERSION + "] Debug for " + moduleName + ": ON", "#B3EBF2");
      return;
    }

    if (action === "off") {
      setModule(moduleName, false);
      echo("[" + VERSION + "] Debug for " + moduleName + ": OFF", "#B3EBF2");
      return;
    }

    echo("[" + VERSION + "] Unknown command. Type: debug", "red");
  }

  main();
})();

/*
GHunt V2.8
Alias Name: ghunt
Alias Pattern: ghunt
Script Type: JavaScript Alias

Required Alias(s):
- debug

Required Trigger(s):
- GHunt Target Counter

Optional Alias(s)/Trigger(s):
- none

Commands:
- ghunt
- ghunt start
- ghunt stop
- ghunt status
- ghunt target <name>
- ghunt skill <skill>
- ghunt delay <ms>
- ghunt wait <minutes>
- ghunt lootwait <ms>
- ghunt record
- ghunt save <path>
- ghunt discard
- ghunt list
- ghunt add <path> <steps>
- ghunt remove <path>
- ghunt path <path>
- ghunt walk <path>
- ghunt back <path>
- ghunt clear
- ghunt reset
*/

try {
  (function () {
    var VERSION = "GHunt V2.8";
    var STORE_KEY = "GenesisGHunt";
    var DEBUG_MODULE = "ghunt";

    function echo(message, color) {
      if (window.gwc && gwc.output && typeof gwc.output.append === "function") {
        gwc.output.append(String(message), color || "#B3EBF2");
        return;
      }

      if (window.console && console.log) {
        console.log(String(message));
      }
    }

    function debug(message) {
      if (window.GenesisDebug && typeof GenesisDebug.log === "function") {
        GenesisDebug.log(DEBUG_MODULE, message);
      }
    }

    function huntEcho(message) {
      /*
        GHunt is intentionally more verbose than the other helpers so the user
        can see scan/kill/move decisions while hunting.
      */
      echo("[GHunt] " + String(message), "#B3EBF2");
    }

        function debugStatus() {
      if (window.GenesisDebug && typeof GenesisDebug.enabled === "function") {
        return GenesisDebug.enabled(DEBUG_MODULE) ? "ON" : "OFF";
      }

      return "OFF";
    }

    function clean(value) {
      return String(value || "").replace(/\s+/g, " ").trim();
    }

    function lower(value) {
      return clean(value).toLowerCase();
    }

    function getUserdata() {
      if (!window.gwc) window.gwc = {};
      if (!gwc.userdata) gwc.userdata = {};
      if (!gwc.userdata[STORE_KEY] || typeof gwc.userdata[STORE_KEY] !== "object") {
        gwc.userdata[STORE_KEY] = {};
      }
      return gwc.userdata[STORE_KEY];
    }

    function defaultState() {
      return {
        enabled: false,
        target: "",
        skill: "",
        path: "",
        delay: 200,
        loopWaitMinutes: 0,
        loopWaiting: false,
        scanDelay: 1500,
        lootWait: 3000,
        lootWaiting: false,
        awaitingDeath: false,
        roomTargetSeen: false,
        roomTargetCount: 0,
        attackIndex: 1,
        roomFailureCount: 0,
        roomScanArmed: false,
        afterExitLine: false,
        scanToken: 0,
        activeScanToken: 0,
        recording: false,
        recordBuffer: [],
        paths: {},
        currentCounts: {},
        busy: false,
        walking: false,
        returningHome: false,
        returnQueue: [],
        walkQueue: [],
        pendingKills: []
      };
    }

    function getState() {
      var state = getUserdata();
      var defaults = defaultState();
      var key;

      for (key in defaults) {
        if (Object.prototype.hasOwnProperty.call(defaults, key) && typeof state[key] === "undefined") {
          state[key] = defaults[key];
        }
      }

      if (!state.paths || typeof state.paths !== "object") state.paths = {};
      if (!Array.isArray(state.recordBuffer)) state.recordBuffer = [];
      if (!state.currentCounts || typeof state.currentCounts !== "object") state.currentCounts = {};
      if (!Array.isArray(state.walkQueue)) state.walkQueue = [];
      if (!Array.isArray(state.returnQueue)) state.returnQueue = [];
      if (typeof state.returningHome !== "boolean") state.returningHome = false;
      if (!Array.isArray(state.pendingKills)) state.pendingKills = [];
      if (!state.delay || isNaN(Number(state.delay))) state.delay = 200;
      if (typeof state.loopWaitMinutes === "undefined" || isNaN(Number(state.loopWaitMinutes))) state.loopWaitMinutes = 0;
      if (typeof state.loopWaiting !== "boolean") state.loopWaiting = false;
      if (!state.scanDelay || isNaN(Number(state.scanDelay))) state.scanDelay = 1500;
      if (typeof state.lootWait === "undefined" || isNaN(Number(state.lootWait))) state.lootWait = 3000;
      if (typeof state.lootWaiting !== "boolean") state.lootWaiting = false;
      if (typeof state.awaitingDeath !== "boolean") state.awaitingDeath = false;
      if (typeof state.roomTargetSeen !== "boolean") state.roomTargetSeen = false;
      if (typeof state.roomTargetCount === "undefined" || isNaN(Number(state.roomTargetCount))) state.roomTargetCount = 0;
      if (typeof state.attackIndex === "undefined" || isNaN(Number(state.attackIndex))) state.attackIndex = 1;
      if (typeof state.roomFailureCount === "undefined" || isNaN(Number(state.roomFailureCount))) state.roomFailureCount = 0;
      if (typeof state.roomScanArmed !== "boolean") state.roomScanArmed = false;
      if (typeof state.afterExitLine !== "boolean") state.afterExitLine = false;
      if (typeof state.scanToken === "undefined" || isNaN(Number(state.scanToken))) state.scanToken = 0;
      if (typeof state.activeScanToken === "undefined" || isNaN(Number(state.activeScanToken))) state.activeScanToken = 0;

      return state;
    }

    function saveState() {
      var state = getState();

      try {
        localStorage.setItem(STORE_KEY, JSON.stringify(state));
      } catch (error) {
        debug("localStorage save failed: " + error.message);
      }
    }

    function loadStateBackup() {
      var saved;

      try {
        saved = JSON.parse(localStorage.getItem(STORE_KEY) || "null");
      } catch (error) {
        saved = null;
      }

      if (saved && typeof saved === "object") {
        gwc.userdata[STORE_KEY] = saved;
      }

      return getState();
    }

    function sendCommand(command) {
      if (!command) return;

      debug("send: " + command);

      try {
        if (window.gwc && gwc.connection && typeof gwc.connection.send === "function") {
          gwc.connection.send(command, true);
          return;
        }
      } catch (errorOne) {
        debug("send true failed: " + errorOne.message);
      }

      try {
        if (window.gwc && gwc.connection && typeof gwc.connection.send === "function") {
          gwc.connection.send(command);
          return;
        }
      } catch (errorTwo) {
        debug("send failed: " + errorTwo.message);
      }

      try {
        if (typeof send === "function") {
          send(command);
        }
      } catch (errorThree) {
        debug("send fallback failed: " + errorThree.message);
      }
    }

    function getRawInput() {
      function strip(value) {
        return clean(value).replace(/^ghunt(?:\s+|$)/i, "").trim();
      }

      function numericParts(obj) {
        var keys;
        var out = [];
        var i;
        var key;
        var value;

        if (!obj || typeof obj !== "object") return "";

        keys = Object.keys(obj)
          .filter(function (k) { return /^\d+$/.test(k); })
          .map(function (k) { return parseInt(k, 10); })
          .sort(function (a, b) { return a - b; });

        for (i = 0; i < keys.length; i += 1) {
          key = keys[i];
          value = clean(obj[key]);

          if (!value) continue;
          if (key === 0 && /^ghunt$/i.test(value)) continue;

          out.push(value);
        }

        return strip(out.join(" "));
      }

      function fromObject(obj) {
        var numeric;

        if (!obj || typeof obj !== "object") return "";

        /*
          Genesis webclient alias args commonly work like:
            args[1] = first word after alias
            args[2] = second word after alias
            args["*"] = full wildcard/rest

          So ghunt save dewar should become:
            save dewar
          not just:
            save
        */
        if (obj["*"]) return strip(obj["*"]);
        if (obj.args) return strip(obj.args);
        if (obj.arg) return strip(obj.arg);
        if (obj.rest) return strip(obj.rest);
        if (obj.commandLine) return strip(obj.commandLine);
        if (obj.commandline) return strip(obj.commandline);
        if (obj.fullCommand) return strip(obj.fullCommand);
        if (obj.fullcommand) return strip(obj.fullcommand);
        if (obj.input) return strip(obj.input);
        if (obj.text) return strip(obj.text);
        if (obj.line) return strip(obj.line);
        if (obj.command) return strip(obj.command);
        if (obj.raw) return strip(obj.raw);
        if (obj.original) return strip(obj.original);

        numeric = numericParts(obj);
        if (numeric) return numeric;

        return "";
      }

      function fallbackFromInput() {
        var fields;
        var i;
        var value;

        try {
          if (document.activeElement && typeof document.activeElement.value === "string") {
            value = clean(document.activeElement.value);
            if (/^ghunt(?:\s+|$)/i.test(value)) return strip(value);
          }

          fields = document.querySelectorAll("input, textarea");
          for (i = 0; i < fields.length; i += 1) {
            value = clean(fields[i].value);
            if (/^ghunt(?:\s+|$)/i.test(value)) return strip(value);
          }
        } catch (error) {}

        return "";
      }

      var raw = "";

      try {
        if (typeof args !== "undefined") {
          if (typeof args === "string") raw = strip(args);
          else if (Array.isArray(args)) raw = strip(args.join(" "));
          else raw = fromObject(args);
        }

        if (!raw && typeof matches !== "undefined") {
          if (typeof matches === "string") raw = strip(matches);
          else if (Array.isArray(matches)) raw = strip(matches.join(" "));
          else raw = fromObject(matches);
        }

        if (!raw) raw = fallbackFromInput();
      } catch (error) {}

      return raw;
    }

    function isMovementCommand(command) {
      var value = lower(command);
      var allowed = {
        n: true, s: true, e: true, w: true,
        ne: true, nw: true, se: true, sw: true,
        u: true, d: true,
        north: true, south: true, east: true, west: true,
        northeast: true, northwest: true, southeast: true, southwest: true,
        up: true, down: true,
        out: true, in: true, enter: true
      };

      return !!allowed[value];
    }

    function normalizeDirection(command) {
      var value = lower(command);
      var map = {
        north: "n", south: "s", east: "e", west: "w",
        northeast: "ne", northwest: "nw", southeast: "se", southwest: "sw",
        up: "u", down: "d"
      };

      return map[value] || value;
    }

    function findCommandInput() {
      var candidates = [
        "#input",
        "input#input",
        "textarea#input",
        "input[name='input']",
        "textarea[name='input']",
        ".input input",
        ".input textarea",
        "#command",
        "#commandInput"
      ];
      var i;
      var el;

      for (i = 0; i < candidates.length; i += 1) {
        el = document.querySelector(candidates[i]);
        if (el) return el;
      }

      return document.querySelector("input, textarea");
    }

    function installRecorderListener() {
      var input = findCommandInput();

      if (!input) {
        echo("[GHunt] Command input not found. Recorder could not attach.", "red");
        return false;
      }

      removeRecorderListener();

      window.GenesisGHuntRecorderHandler = function (event) {
        var state;
        var value;

        if (!event || event.key !== "Enter") return;

        state = getState();
        if (!state.recording) return;

        value = clean(input.value);
        if (!value || /^ghunt(?:\s+|$)/i.test(value)) return;

        if (!isMovementCommand(value)) {
          debug("ignored non-movement while recording: " + value);
          return;
        }

        state.recordBuffer.push(normalizeDirection(value));
        saveState();
        debug("recorded: " + normalizeDirection(value));
      };

      input.addEventListener("keydown", window.GenesisGHuntRecorderHandler);
      window.GenesisGHuntRecorderInput = input;

      return true;
    }

    function removeRecorderListener() {
      try {
        if (window.GenesisGHuntRecorderInput && window.GenesisGHuntRecorderHandler) {
          window.GenesisGHuntRecorderInput.removeEventListener("keydown", window.GenesisGHuntRecorderHandler);
        }
      } catch (error) {}

      window.GenesisGHuntRecorderInput = null;
      window.GenesisGHuntRecorderHandler = null;
    }

    function parseSteps(text) {
      var input = clean(text).replace(/,/g, " ");
      var tokens = input ? input.split(/\s+/) : [];
      var out = [];
      var i;
      var token;
      var m;
      var count;
      var dir;
      var j;

      for (i = 0; i < tokens.length; i += 1) {
        token = lower(tokens[i]);
        if (!token) continue;

        m = token.match(/^(\d+)([a-z]+)$/i);
        if (m) {
          count = parseInt(m[1], 10);
          dir = normalizeDirection(m[2]);
          for (j = 0; j < count; j += 1) out.push(dir);
        } else {
          out.push(normalizeDirection(token));
        }
      }

      return out;
    }

    function reverseSteps(steps) {
      var reverseMap = {
        n: "s", s: "n", e: "w", w: "e",
        ne: "sw", nw: "se", se: "nw", sw: "ne",
        u: "d", d: "u", out: "in", in: "out", enter: "out"
      };
      var out = [];
      var i;

      for (i = steps.length - 1; i >= 0; i -= 1) {
        out.push(reverseMap[steps[i]] || steps[i]);
      }

      return out;
    }

    function compactSteps(steps) {
      var out = [];
      var last = null;
      var count = 0;
      var i;

      function flush() {
        if (!last) return;
        out.push(count > 1 ? String(count) + last : last);
      }

      for (i = 0; i < steps.length; i += 1) {
        if (steps[i] === last) count += 1;
        else {
          flush();
          last = steps[i];
          count = 1;
        }
      }

      flush();
      return out.join(", ");
    }

    function showHelp() {
      var state = getState();
      var lines = [];

      lines.push("[" + VERSION + "]");
      lines.push("Status: " + (state.enabled ? "ON" : "OFF") + " | Path: " + (state.path || "none") + " | Target: " + (state.target || "none") + " | Skill: " + (state.skill || "none") + " | Delay: " + state.delay + "ms | Wait: " + state.loopWaitMinutes + "m | Debug: " + debugStatus());
      lines.push("");
      lines.push("Commands:");
      lines.push("  ghunt                         Show command list");
      lines.push("  ghunt start                   Start hunting current path/target");
      lines.push("  ghunt stop                    Stop hunting/path walking");
      lines.push("  ghunt status                  Show status");
      lines.push("  ghunt target <name>           Set hunt target keyword");
      lines.push("  ghunt skill <skill>           Set skill to fire after first kill");
      lines.push("  ghunt delay <ms>              Set command delay");
      lines.push("  ghunt wait <minutes>          Wait before restarting path loop");
      lines.push("  ghunt lootwait <ms>           Wait after room is clear before moving");
      lines.push("  ghunt clear                   Clear current target/count state");
      lines.push("  ghunt reset                   Restore defaults");
      lines.push("");
      lines.push("Path commands:");
      lines.push("  ghunt record                  Start recording movement");
      lines.push("  ghunt save <path>             Save recorded path and stop recording");
      lines.push("  ghunt discard                 Stop/discard recording");
      lines.push("  ghunt list                    Show saved paths");
      lines.push("  ghunt add <path> <steps>      Manually save path");
      lines.push("  ghunt remove <path>           Delete saved path");
      lines.push("  ghunt path <path>             Set hunting path");
      lines.push("  ghunt walk <path>             Walk path once without hunting");
      lines.push("  ghunt back <path>             Walk reverse path once without hunting");

      echo(lines.join("\n"), "#B3EBF2");
    }

    function status() {
      var state = getState();
      var lines = [];
      var targetCount = state.target ? (state.currentCounts[state.target] || 0) : 0;

      lines.push("[" + VERSION + "]");
      lines.push("Status: " + (state.enabled ? "ON" : "OFF"));
      lines.push("Path: " + (state.path || "none"));
      lines.push("Target: " + (state.target || "none"));
      lines.push("Skill: " + (state.skill || "none"));
      lines.push("Visible target count: " + targetCount);
      lines.push("Recording: " + (state.recording ? "YES (" + state.recordBuffer.length + " step(s))" : "NO"));
      lines.push("Walking: " + (state.walking ? "YES (" + state.walkQueue.length + " queued)" : "NO"));
      lines.push("Loop waiting: " + (state.loopWaiting ? "YES" : "NO"));
      lines.push("Delay: " + state.delay + "ms");
      lines.push("Loop wait: " + state.loopWaitMinutes + " minute(s)");
      lines.push("Room scan delay: " + state.scanDelay + "ms");
      lines.push("Loot wait: " + state.lootWait + "ms");
      lines.push("Loot waiting: " + (state.lootWaiting ? "YES" : "NO"));
      lines.push("Awaiting death: " + (state.awaitingDeath ? "YES" : "NO"));

      echo(lines.join("\n"), "#B3EBF2");
    }

    function listPaths() {
      var state = getState();
      var names = Object.keys(state.paths || {});
      var lines = [];
      var i;
