        such as:
        "The grim gray-bearded male human and the lithe gangly female dewar are fighting each other."
      */
      if (/\bare fighting each other\b/.test(text)) return true;
      if (/\bis fighting\b/.test(text)) return true;
      if (/\bare fighting\b/.test(text)) return true;
      if (/\bseems to be fighting\b/.test(text)) return true;
      if (/\bis busy fighting\b/.test(text)) return true;

