      if (text.indexOf("you don't find any") !== -1) return true;
      if (text.indexOf("you cannot attack") !== -1) return true;
      if (text.indexOf("you can't attack") !== -1) return true;
      if (text.indexOf("you are already fighting") !== -1) return true;
      if (text.indexOf("is already fighting") !== -1) return true;
      if (text.indexOf("are already fighting") !== -1) return true;

      if (target && text.indexOf(target) !== -1) {
        if (text.indexOf(" is fighting ") !== -1) return true;
        if (text.indexOf(" are fighting ") !== -1) return true;
        if (text.indexOf(" seems to be fighting ") !== -1) return true;
        if (text.indexOf(" is busy fighting ") !== -1) return true;
