      out("Debug: " + (debugEnabled() ? "ON" : "OFF"), "#88ccff");
      out("Commands:", "#ffcc66");
      out("  imbue                 Show command list", "#cccccc");
      out("  imbue show            Show/open tracker window", "#cccccc");
      out("  imbue hide            Hide tracker window", "#cccccc");
      out("  imbue reset           Reset session counts", "#cccccc");
      out("  imbue position reset  Reset window position", "#cccccc");
      out("  imbue debug on        Enable debug output", "#cccccc");
      out("  imbue debug off       Disable debug output", "#cccccc");
    }

    function handleCountBlock(counts) {
      var d = ensureData();
      var unusual = Number(counts && counts.unusual || 0);
      var peculiar = Number(counts && counts.peculiar || 0);
      var exotic = Number(counts && counts.exotic || 0);
      var total = unusual + peculiar + exotic;

      d.session.unusual += unusual;
      d.session.peculiar += peculiar;
      d.session.exotic += exotic;
      d.session.total += total;

      ensureWindow();
      render();

      debug("Added block: unusual=" + unusual + " peculiar=" + peculiar + " exotic=" + exotic + " total=" + total);
    }

    /*
      Public API used by the Imbue Count trigger.
    */
    window.GenesisImbueTracker = window.GenesisImbueTracker || {};
    window.GenesisImbueTracker.version = VERSION;
    window.GenesisImbueTracker.addBlock = handleCountBlock;
    window.GenesisImbueTracker.render = render;
    window.GenesisImbueTracker.ensureWindow = ensureWindow;

    var parts = getArgs();
    var cmd = lower(parts[0] || "");
    var sub = lower(parts[1] || "");

    if (!cmd) {
      ensureWindow();
      showHelp();
      return;
    }

    if (cmd === "show" || cmd === "open") {
      showWindow();
      return;
    }

    if (cmd === "hide" || cmd === "close") {
      hideWindow();
      return;
    }

    if (cmd === "reset") {
      resetCounts();
      return;
    }

    if (cmd === "position" && sub === "reset") {
      resetPosition();
      return;
    }

    if (cmd === "debug") {
      setDebug(sub);
      return;
    }

    if (cmd === "help" || cmd === "?") {
      ensureWindow();
      showHelp();
      return;
    }

    out("Unknown command: " + cmd, "#ffcc66");
    showHelp();
  })();
} catch (e) {
  try {
    gwc.output.append("[Imbue ERROR] " + e.name + ": " + e.message, "#ff6666");
  } catch (ignore) {}
}

/*
KA V1.2
Alias Name: ka
Alias Pattern: ka
Script Type: JavaScript Alias

Required Alias(s):
- debug

Required Trigger(s):
- Target Counter

Optional Alias(s)/Trigger(s):
- none

Commands:
- ka help
- ka
- ka target <target>
- ka skill <skill>
- ka <skill>
- ka <target> <skill>
- ka clear
- ka clear target
- ka clear skill
*/

(function () {
  "use strict";

  var VERSION = "KA V1.2";
  var STORE_KEY = "genesisKA";
  var DEBUG_MODULE = "ka";

  // ---------- Output helpers ----------
  function echo(message, color) {
    if (window.gwc && gwc.output && typeof gwc.output.append === "function") {
      gwc.output.append(String(message), color || "#B3EBF2");
      return;
    }

    if (window.console && console.log) {
      console.log(String(message));
    }
  }

  function debug(message) {
    if (window.GenesisDebug && typeof GenesisDebug.log === "function") {
      GenesisDebug.log(DEBUG_MODULE, message);
    }
  }

  function sendCommand(command) {
    if (!command) return;

    debug("SEND: " + command);

    if (window.gwc && gwc.connection && typeof gwc.connection.send === "function") {
      gwc.connection.send(command);
      return;
    }

    if (typeof send === "function") {
      send(command);
    }
  }

  function safeLower(value) {
    return String(value || "").trim().toLowerCase();
  }

  function cleanSpaces(value) {
    return String(value || "").replace(/\s+/g, " ").trim();
  }

  // ---------- Storage ----------
  function ensureUserdata() {
    if (!window.gwc) window.gwc = {};
    if (!gwc.userdata) gwc.userdata = {};
    if (!gwc.userdata[STORE_KEY] || typeof gwc.userdata[STORE_KEY] !== "object") {
      gwc.userdata[STORE_KEY] = {};
    }
    return gwc.userdata[STORE_KEY];
  }

  function getStore() {
    var store = ensureUserdata();

    if (typeof store.target !== "string") store.target = "";
    if (typeof store.skill !== "string") store.skill = "";
    if (!store.pending || typeof store.pending !== "object") store.pending = null;

    return store;
  }

  // ---------- Public KA helper used by Target Counter trigger ----------
  window.GenesisKA = window.GenesisKA || {};

  window.GenesisKA.version = VERSION;

  window.GenesisKA.getStore = function () {
    return getStore();
  };

  window.GenesisKA.debug = function (message) {
    debug(message);
  };

  window.GenesisKA.sendCommand = function (command) {
    sendCommand(command);
  };

  window.GenesisKA.normalizeTarget = function (target) {
    return cleanSpaces(target).toLowerCase();
  };

  window.GenesisKA.pluralize = function (target) {
    var t = window.GenesisKA.normalizeTarget(target);

    if (!t) return "";

    if (/\bdrow$/.test(t)) return t;
    if (/\bdwarf$/.test(t)) return t.replace(/dwarf$/, "dwarves");
    if (/\belf$/.test(t)) return t.replace(/elf$/, "elves");
    if (/[^aeiou]y$/.test(t)) return t.replace(/y$/, "ies");
    if (/fe$/.test(t)) return t.replace(/fe$/, "ves");
    if (/f$/.test(t)) return t.replace(/f$/, "ves");
    if (/s$/.test(t)) return t + "es";

    return t + "s";
  };

  window.GenesisKA.ordinal = function (number) {
    var words = [
      "",
      "first",
      "second",
      "third",
      "fourth",
      "fifth",
      "sixth",
      "seventh",
      "eighth",
      "ninth",
      "tenth",
      "eleventh",
      "twelfth",
      "thirteenth",
      "fourteenth",
      "fifteenth"
    ];

    return words[number] || String(number) + "th";
  };

  window.GenesisKA.queueCount = function (target, skill) {
    var store = getStore();
    var cleanTarget = window.GenesisKA.normalizeTarget(target);
    var cleanSkill = cleanSpaces(skill || "");
    var pluralTarget;

    if (!cleanTarget) {
      echo("[" + VERSION + "] No target set. Use: ka target <target>", "red");
      return;
    }

    pluralTarget = window.GenesisKA.pluralize(cleanTarget);

    store.pending = {
      target: cleanTarget,
      skill: cleanSkill,
      createdAt: Date.now()
    };

    debug("Queued target count. target=" + cleanTarget + ", plural=" + pluralTarget + ", skill=" + (cleanSkill || "none"));
    sendCommand("count " + pluralTarget);
  };

  window.GenesisKA.handleCountResult = function (count) {
    var store = getStore();
    var pending = store.pending;
    var target;
    var skill;
    var i;

    if (!pending || !pending.target) {
      debug("Target Counter fired but no KA pending action exists.");
      return;
    }

    target = pending.target;
    skill = pending.skill || "";
    store.pending = null;

    count = parseInt(count, 10) || 0;

    debug("Target Counter result received. count=" + count + ", target=" + target + ", skill=" + (skill || "none"));

    if (count <= 0) {
      echo("[" + VERSION + "] No " + target + " found.", "#B3EBF2");
      return;
    }

    // First target always starts combat with a normal kill command.
    sendCommand("kill " + target);

    // Some Genesis skills cannot start combat, so fire the skill after kill <target>.
    if (skill) {
      sendCommand(skill);
    }

    // Remaining targets use numbered kill commands.
    for (i = 2; i <= count; i += 1) {
      sendCommand("kill " + window.GenesisKA.ordinal(i) + " " + target);
    }
  };

  // ---------- Alias parsing ----------
  function getRawInput() {
    if (typeof args === "undefined") return "";

    if (typeof args[0] === "string") return args[0];
    if (typeof args["*"] === "string") return args["*"];

    return "";
  }

  function getParts() {
    var raw = cleanSpaces(getRawInput());
    var parts;

    if (!raw) return [];

    parts = raw.split(/\s+/);

    if (parts.length && safeLower(parts[0]) === "ka") {
      parts.shift();
    }

    return parts;
  }

  // ---------- Display ----------
  function debugStatus() {
    if (window.GenesisDebug && typeof GenesisDebug.enabled === "function") {
      return GenesisDebug.enabled(DEBUG_MODULE) ? "ON" : "OFF";
    }

    return "OFF";
  }

  function showHelp() {
    var store = getStore();
    var lines = [];

    lines.push("[" + VERSION + "]");
    lines.push("Status:");
    lines.push("  Target: " + (store.target || "none"));
    lines.push("  Skill:  " + (store.skill || "none"));
    lines.push("  Debug:  " + debugStatus());
    lines.push("");
    lines.push("Commands:");
    lines.push("  ka help                 Show command list");
    lines.push("  ka                      Count saved target, then run kill/skill chain");
    lines.push("  ka target <target>      Save default target");
    lines.push("  ka skill <skill>        Save default skill");
    lines.push("  ka <skill>              Use saved target with this skill");
    lines.push("  ka <target> <skill>     Use target and skill for this run only");
    lines.push("  ka clear                Clear saved target and skill");
    lines.push("  ka clear target         Clear saved target");
    lines.push("  ka clear skill          Clear saved skill");
    lines.push("");
    lines.push("Combat order after count:");
    lines.push("  kill <target>");
    lines.push("  <skill>");
    lines.push("  kill second <target>");
    lines.push("  kill third <target>");

    echo(lines.join("\n"), "#B3EBF2");
  }

  function setTarget(parts) {
    var store = getStore();
    var target = window.GenesisKA.normalizeTarget(parts.join(" "));

    if (!target) {
      echo("[" + VERSION + "] Use: ka target <target>", "red");
      return;
    }

    store.target = target;
    echo("[" + VERSION + "] Target saved: " + target, "#B3EBF2");
    debug("Saved target: " + target);
  }

  function setSkill(parts) {
    var store = getStore();
    var skill = cleanSpaces(parts.join(" "));

    if (!skill) {
      echo("[" + VERSION + "] Use: ka skill <skill>", "red");
      return;
    }

    store.skill = skill;
    echo("[" + VERSION + "] Skill saved: " + skill, "#B3EBF2");
    debug("Saved skill: " + skill);
  }

  function clearSetting(which) {
    var store = getStore();

    if (!which) {
      store.target = "";
      store.skill = "";
      store.pending = null;
      echo("[" + VERSION + "] Cleared saved target and skill.", "#B3EBF2");
      debug("Cleared target, skill, and pending action.");
      return;
    }

    if (which === "target") {
      store.target = "";
      store.pending = null;
      echo("[" + VERSION + "] Cleared saved target.", "#B3EBF2");
      debug("Cleared target and pending action.");
      return;
    }

    if (which === "skill") {
      store.skill = "";
      echo("[" + VERSION + "] Cleared saved skill.", "#B3EBF2");
      debug("Cleared skill.");
      return;
    }

    echo("[" + VERSION + "] Unknown clear option. Use: ka clear, ka clear target, or ka clear skill", "red");
  }

  function runSaved() {
    var store = getStore();

    if (!store.target) {
      echo("[" + VERSION + "] No target saved. Use: ka target <target>", "red");
      return;
    }

    window.GenesisKA.queueCount(store.target, store.skill);
  }

  function runSingleArgument(value) {
    var store = getStore();
    var arg = cleanSpaces(value);

    if (!arg) {
      runSaved();
      return;
    }

    if (store.target) {
      // New V1.2 behavior:
      // ka <skill> uses the saved target and applies this skill after kill <target>.
      window.GenesisKA.queueCount(store.target, arg);
      return;
    }

    // No saved target exists, so treat the single argument as a temporary target.
    window.GenesisKA.queueCount(arg, store.skill);
  }

  function runTargetAndSkill(parts) {
    var target = parts[0];
    var skill = parts.slice(1).join(" ");

    window.GenesisKA.queueCount(target, skill);
  }

  function main() {
    var parts = getParts();
    var first = safeLower(parts[0]);

    getStore();

    if (!parts.length) {
      runSaved();
      return;
    }

    if (first === "help") {
      showHelp();
      return;
    }

    if (first === "target") {
      setTarget(parts.slice(1));
      return;
    }

    if (first === "skill") {
      setSkill(parts.slice(1));
      return;
    }

    if (first === "clear") {
      clearSetting(safeLower(parts[1]));
      return;
    }

    if (parts.length === 1) {
      runSingleArgument(parts[0]);
      return;
    }

    runTargetAndSkill(parts);
  }

  main();
})();

/*
Updated/Improved by Vitro
Original Author: Faery


Alias
Pattern: package
Type: Javascript

Commands:
 - package create
 - package install
 - package help
 - package debug

Purpose:
 - package create: fetches real Genesis aliases.json/triggers.json, lets you select items, and downloads a package.
 - package install: installs aliases/triggers from a selected package JSON.
 - package debug: shows detected character/token/source information.

Required Trigger(s):
 - None

Required Alias(s):
 - None
*/

try {
  (function () {
    var VERSION = "Genesis Package Manager v4 STRICT";
    var MSG = "#B3EBF2";
    var OK = "#80ff80";
    var ERR = "#ff6666";
    var WARN = "#ffcc66";

    function out(msg, color) {
      try {
        gwc.output.append("[Package] " + String(msg), color || MSG);
      } catch (e) {
        try { console.log("[Package] " + msg); } catch (ignore) {}
      }
    }

    function clean(text) {
      return String(text || "").replace(/\s+/g, " ").replace(/^\s+|\s+$/g, "");
    }

    function escapeHtml(text) {
      return $("<div>").text(String(text || "")).html();
    }

    function getArgText() {
      try {
        if (typeof args !== "undefined") {
          if (typeof args["*"] !== "undefined") {
            return clean(String(args["*"]).replace(/^package\s*/i, ""));
          }
          if (typeof args[1] !== "undefined") {
            return clean(args[1]);
          }
          if (typeof args[0] !== "undefined") {
            return clean(String(args[0]).replace(/^package\s*/i, ""));
          }
        }
      } catch (e) {}
      return "";
    }

    function getLoginName() {
      try {
        if (mud && mud.gmcp && mud.gmcp["char.login"] && mud.gmcp["char.login"].name) {
          return clean(mud.gmcp["char.login"].name);
        }
      } catch (e1) {}

      try {
        if (gwc && gwc.gmcp && gwc.gmcp.data && gwc.gmcp.data.char && gwc.gmcp.data.char.login && gwc.gmcp.data.char.login.name) {
          return clean(gwc.gmcp.data.char.login.name);
        }
      } catch (e2) {}

      try {
        if (gwc && gwc.gmcp && gwc.gmcp.data && gwc.gmcp.data.character && gwc.gmcp.data.character.login && gwc.gmcp.data.character.login.name) {
          return clean(gwc.gmcp.data.character.login.name);
        }
      } catch (e3) {}

      return "";
    }

    function getToken() {
      var token = "";

      /*
        This intentionally mirrors the older working package alias:
        mud.gmcp["core.token"][0] + ... + [7]
      */
      try {
        if (mud && mud.gmcp && mud.gmcp["core.token"]) {
          token =
            String(mud.gmcp["core.token"][0] || "") +
            String(mud.gmcp["core.token"][1] || "") +
            String(mud.gmcp["core.token"][2] || "") +
            String(mud.gmcp["core.token"][3] || "") +
            String(mud.gmcp["core.token"][4] || "") +
            String(mud.gmcp["core.token"][5] || "") +
            String(mud.gmcp["core.token"][6] || "") +
            String(mud.gmcp["core.token"][7] || "");
        }
      } catch (e1) {}

      if (!token) {
        try {
          if (gwc && gwc.gmcp && gwc.gmcp.data && gwc.gmcp.data.core && gwc.gmcp.data.core.token) {
            var raw = gwc.gmcp.data.core.token;
            if (Array.isArray(raw)) token = raw.slice(0, 8).join("");
            else token = String(raw).substring(0, 8);
          }
        } catch (e2) {}
      }

      return clean(token).substring(0, 8);
    }

    function timestamp() {
      var d = new Date();
      return d.getFullYear() + "-" +
        String(d.getMonth() + 1).padStart(2, "0") + "-" +
        String(d.getDate()).padStart(2, "0") + "_" +
        String(d.getHours()).padStart(2, "0") +
        String(d.getMinutes()).padStart(2, "0") +
        String(d.getSeconds()).padStart(2, "0");
    }

    function getUrl(type) {
      var login = getLoginName();
      return "https://www.genesismud.org/player_file/" + encodeURIComponent(login) + "/" + type + ".json";
    }

    function fetchGenesisJson(type) {
      var login = getLoginName();
      var token = getToken();

      if (!login) {
        return Promise.reject(new Error("Could not detect character name from GMCP. Reconnect and try again."));
      }

      if (!token || token.length < 8) {
        return Promise.reject(new Error("Could not detect 8-character GMCP token. Reconnect and try again."));
      }

      return new Promise(function (resolve, reject) {
        $.ajax({
          type: "GET",
          url: getUrl(type),
          cache: false,
          beforeSend: function (request) {
            request.setRequestHeader("GMCP-Token", token);
          },
          success: function (data) {
            try {
              if (typeof data === "string") {
                data = JSON.parse(data);
              }
              if (!Array.isArray(data)) {
                reject(new Error(type + ".json did not return an array."));
                return;
              }
              resolve(data);
            } catch (e) {
              reject(new Error("Could not parse " + type + ".json: " + e.message));
            }
          },
          error: function (jqXHR, textStatus, errorThrown) {
            var status = jqXHR && jqXHR.status ? "HTTP " + jqXHR.status : "no HTTP status";
            reject(new Error("Could not fetch " + type + ".json (" + status + ", " + (textStatus || "error") + (errorThrown ? ", " + errorThrown : "") + ")."));
          }
        });
      });
    }

    function debug() {
      var login = getLoginName();
      var token = getToken();

      out(VERSION, MSG);
      out("Detected character: " + (login || "(none)"), login ? OK : ERR);
      out("Detected token length: " + token.length, token.length === 8 ? OK : ERR);

      if (login) {
        out("Aliases URL: " + getUrl("aliases"), MSG);
        out("Triggers URL: " + getUrl("triggers"), MSG);
      }

      out("If package create fails, type package debug and send me the output.", WARN);
    }

    function removePopup() {
      try { $("#genesis-package-popup").remove(); } catch (e) {}
    }

    function buttonHtml(id, label) {
      return "<button id='" + id + "' type='button' style='" +
        "padding:5px 10px;" +
        "background:rgba(255,255,255,0.10);" +
        "border:1px solid #888;" +
        "color:#ddd;" +
        "cursor:pointer;" +
        "font-family:monospace;" +
        "border-radius:4px;" +
      "'>" + escapeHtml(label) + "</button>";
    }

    function normalizeAlias(item) {
      item = item || {};
      item.enabled = item.enabled !== false;
      item.value = item.value || "";
      item.script = item.script || {};
      item.script.language = item.script.language || "javascript";
      item.script.data = item.script.data || "";
      item.script.user_function = item.script.user_function || {};
      return item;
    }

    function normalizeTrigger(item) {
      item = item || {};
      item.enabled = item.enabled !== false;
      item.name = item.name || "";
      item.type = item.type || "regexp";
      item.value = item.value || "";
      item.script = item.script || {};
      item.script.language = item.script.language || "javascript";
      item.script.data = item.script.data || "";
      item.script.user_function = item.script.user_function || {};
      return item;
    }

    function downloadPackage(packageData) {
      var filename = "Genesis_Selected_Package_" + timestamp() + ".json";
      var blob = new Blob([JSON.stringify(packageData, null, 2)], { type: "application/json" });
      var url = URL.createObjectURL(blob);
      var a = document.createElement("a");

      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();

      setTimeout(function () {
        try { URL.revokeObjectURL(url); } catch (e) {}
        try { document.body.removeChild(a); } catch (e2) {}
      }, 500);

      out("Downloaded: " + filename, OK);
      out("Aliases included: " + (packageData.aliases.length ? packageData.aliases.map(function (a) { return a.value; }).join(", ") : "None"), MSG);
      out("Triggers included: " + (packageData.triggers.length ? packageData.triggers.map(function (t) { return t.name; }).join(", ") : "None"), MSG);
    }

    function showCreatePopup(aliases, triggers) {
      removePopup();

      aliases = (aliases || []).map(normalizeAlias).filter(function (a) { return !!a.value; });
      triggers = (triggers || []).map(normalizeTrigger).filter(function (t) { return !!t.name; });

      aliases.sort(function (a, b) { return String(a.value).localeCompare(String(b.value)); });
      triggers.sort(function (a, b) { return String(a.name).localeCompare(String(b.name)); });

      var popup = document.createElement("div");
      popup.id = "genesis-package-popup";
      popup.style.cssText = [
        "position:fixed",
        "top:8%",
        "left:50%",
        "transform:translateX(-50%)",
        "width:760px",
        "max-width:94vw",
        "height:72vh",
        "background:rgba(0,0,0,0.94)",
        "color:#ddd",
        "border:1px solid #777",
        "box-shadow:0 8px 30px rgba(0,0,0,0.5)",
        "z-index:90",
        "font-family:monospace",
        "display:flex",
        "flex-direction:column",
        "border-radius:6px",
        "overflow:hidden"
      ].join(";");

      var aliasRows = aliases.map(function (a, i) {
        return "<label class='pkg-row' data-search='" + escapeHtml(String(a.value).toLowerCase()) + "' style='display:block;padding:3px 0;'>" +
          "<input type='checkbox' class='pkg-alias' data-index='" + i + "'> " + escapeHtml(a.value) +
        "</label>";
      }).join("");

      var triggerRows = triggers.map(function (t, i) {
        return "<label class='pkg-row' data-search='" + escapeHtml(String(t.name).toLowerCase()) + "' style='display:block;padding:3px 0;'>" +
          "<input type='checkbox' class='pkg-trigger' data-index='" + i + "'> " + escapeHtml(t.name) +
        "</label>";
      }).join("");

      popup.innerHTML =
        "<div style='padding:10px;border-bottom:1px solid #555;display:flex;align-items:center;gap:8px;'>" +
          "<div style='font-weight:bold;flex:1;'>" + escapeHtml(VERSION) + " - Create Package</div>" +
          "<button id='pkg-close' type='button' style='background:#330000;color:#eee;border:1px solid #777;padding:3px 8px;cursor:pointer;'>X</button>" +
        "</div>" +
        "<div style='padding:8px;border-bottom:1px solid #333;color:" + OK + ";'>" +
          "Loaded real Genesis JSON: " + aliases.length + " aliases, " + triggers.length + " triggers. No placeholders will be exported." +
        "</div>" +
        "<div style='padding:8px;border-bottom:1px solid #333;display:flex;gap:8px;align-items:center;'>" +
          "<input id='pkg-search' type='text' placeholder='Search aliases/triggers...' style='flex:1;background:#111;color:#ddd;border:1px solid #555;padding:6px;font-family:monospace;'>" +
          buttonHtml("pkg-select-visible", "Select Visible") +
          buttonHtml("pkg-clear-visible", "Clear Visible") +
        "</div>" +
        "<div style='display:flex;flex:1;min-height:0;'>" +
          "<div style='width:50%;border-right:1px solid #333;display:flex;flex-direction:column;min-height:0;'>" +
            "<div style='padding:8px;border-bottom:1px solid #333;font-weight:bold;'>Aliases (" + aliases.length + ")</div>" +
            "<div style='padding:8px;overflow:auto;flex:1;'>" + (aliasRows || "<div style='color:#888;'>No aliases found.</div>") + "</div>" +
          "</div>" +
          "<div style='width:50%;display:flex;flex-direction:column;min-height:0;'>" +
            "<div style='padding:8px;border-bottom:1px solid #333;font-weight:bold;'>Triggers (" + triggers.length + ")</div>" +
            "<div style='padding:8px;overflow:auto;flex:1;'>" + (triggerRows || "<div style='color:#888;'>No triggers found.</div>") + "</div>" +
          "</div>" +
        "</div>" +
        "<div style='padding:10px;border-top:1px solid #555;display:flex;align-items:center;gap:8px;'>" +
          "<div id='pkg-status' style='flex:1;color:#aaa;'>Selected: 0 aliases, 0 triggers.</div>" +
          buttonHtml("pkg-download", "Download Selected Package") +
        "</div>";

      document.body.appendChild(popup);

      $("#pkg-close").on("click", removePopup);

      function updateStatus() {
        $("#pkg-status").text("Selected: " + $(".pkg-alias:checked").length + " aliases, " + $(".pkg-trigger:checked").length + " triggers.");
      }

      $("#pkg-search").on("input", function () {
        var q = clean($(this).val()).toLowerCase();
        $(".pkg-row").each(function () {
          var hay = String($(this).attr("data-search") || "");
          $(this).toggle(!q || hay.indexOf(q) !== -1);
        });
      });

      $(document).off("change.genesisPackage").on("change.genesisPackage", ".pkg-alias,.pkg-trigger", updateStatus);

      $("#pkg-select-visible").on("click", function () {
        $(".pkg-row:visible input[type='checkbox']").prop("checked", true);
        updateStatus();
      });

      $("#pkg-clear-visible").on("click", function () {
        $(".pkg-row:visible input[type='checkbox']").prop("checked", false);
        updateStatus();
      });

      $("#pkg-download").on("click", function () {
        var selectedAliases = [];
        var selectedTriggers = [];

        $(".pkg-alias:checked").each(function () {
          var idx = parseInt($(this).attr("data-index"), 10);
          if (!isNaN(idx) && aliases[idx]) selectedAliases.push(aliases[idx]);
        });

        $(".pkg-trigger:checked").each(function () {
          var idx = parseInt($(this).attr("data-index"), 10);
          if (!isNaN(idx) && triggers[idx]) selectedTriggers.push(triggers[idx]);
        });

        if (!selectedAliases.length && !selectedTriggers.length) {
          out("No aliases/triggers selected.", WARN);
          return;
        }

        downloadPackage({
          packageName: "Genesis Selected Package",
          createdBy: VERSION,
          createdAt: new Date().toISOString(),
          aliases: selectedAliases,
          triggers: selectedTriggers
        });
      });
    }

    function createPackage() {
      out("Fetching real Genesis aliases.json and triggers.json...", MSG);

      Promise.all([
        fetchGenesisJson("aliases"),
        fetchGenesisJson("triggers")
      ]).then(function (result) {
        out("Fetch successful. Opening package creator.", OK);
        showCreatePopup(result[0], result[1]);
      }).catch(function (e) {
        out(e.message, ERR);
        out("Package creation stopped. No placeholder package was created.", WARN);
        out("Run: package debug", WARN);
      });
    }

    function wait(ms) {
      return new Promise(function (resolve) {
        setTimeout(resolve, ms);
      });
    }

    function clickButtonByText(text) {
      var wanted = clean(text).toLowerCase();
      var found = false;

      $("button").each(function () {
        if (clean($(this).text()).toLowerCase() === wanted) {
          $(this).click();
          found = true;
          return false;
        }
      });

      return found;
    }

    function setInput(selector, value) {
      var el = $(selector).first();
      if (!el.length) return false;
      el.val(value);
      el.trigger("input");
      el.trigger("change");
      return true;
    }

    function setCode(text) {
      try {
        var cm = $(".CodeMirror")[0].CodeMirror;
        cm.setValue(String(text || ""));
        return true;
      } catch (e) {
        return false;
      }
    }

    function isSettingsOpen() {
      try {
        var el = document.getElementById("settings") ||
                 document.getElementById("settingscontent");
        if (!el) return false;
        var r = el.getBoundingClientRect();
        return r.width > 0 && r.height > 0 &&
               window.getComputedStyle(el).display !== "none";
      } catch (e) { return false; }
    }

    function openSettingsTab(type) {
      var alreadyOpen = isSettingsOpen();
      if (!alreadyOpen) {
        try { $("#opensettings").click(); } catch (e) {}
      }
      return wait(alreadyOpen ? 50 : 200).then(function () {
        try { $("#" + type).click(); } catch (e) {}
        return wait(150);
      });
    }

    function findEntry(type, name) {
      var found = false;

      $("#" + type + " .enabled, #" + type + " .disabled").each(function () {
        if (clean($(this).text()) === clean(name)) {
          $(this).click();
          found = true;
          return false;
        }
      });

      return found;
    }

    function setLanguage(language) {
      var lang = String(language || "javascript").toLowerCase();
      clickButtonByText(lang === "javascript" ? "Javascript" : "Commands");
    }

    function saveAndSetEnabled(enabled) {
      clickButtonByText("Save");

      return wait(150).then(function () {
        if (enabled === false) {
          clickButtonByText("Disable");
        }
      });
    }

    function installAlias(item) {
      item = normalizeAlias(item);
      if (!item.value) return Promise.resolve();

      return openSettingsTab("aliases")
        .then(function () {
          if (findEntry("aliases", item.value)) {
            clickButtonByText("Edit");
          } else {
            $("#aliases .addentry").click();
          }
          return wait(200);
        })
        .then(function () {
          setInput(".data input[type='text']", item.value);
          setLanguage(item.script.language);
          return wait(100);
        })
        .then(function () {
          if (!setCode(item.script.data)) {
            throw new Error("Could not write CodeMirror content for alias " + item.value);
          }
          return saveAndSetEnabled(item.enabled);
        })
        .then(function () {
          out("Installed alias: " + item.value, OK);
        });
    }

    function installTrigger(item) {
      item = normalizeTrigger(item);
      if (!item.name) return Promise.resolve();

      return openSettingsTab("triggers")
        .then(function () {
          if (findEntry("triggers", item.name)) {
            clickButtonByText("Edit");
          } else {
            $("#triggers .addentry").click();
          }
          return wait(200);
        })
        .then(function () {
          setInput(".data input.trigger-name", item.name);
          setInput(".data input.trigger-pattern", item.value || "");

          try { $("button[data-type='" + item.type + "']").click(); } catch (e) {}

          setLanguage(item.script.language);
          return wait(80);
        })
        .then(function () {
          if (!setCode(item.script.data)) {
            throw new Error("Could not write CodeMirror content for trigger " + item.name);
          }
          return saveAndSetEnabled(item.enabled);
        })
        .then(function () {
          out("Installed trigger: " + item.name, OK);
        });
    }

    function readPackage(file) {
      return new Promise(function (resolve, reject) {
        var reader = new FileReader();

        reader.onload = function (e) {
          try {
            var data = JSON.parse(e.target.result);
            data.aliases = Array.isArray(data.aliases) ? data.aliases : [];
            data.triggers = Array.isArray(data.triggers) ? data.triggers : [];
            resolve(data);
          } catch (err) {
            reject(err);
          }
        };

        reader.onerror = function () {
          reject(new Error("Could not read selected file."));
        };

        reader.readAsText(file);
      });
    }

    function installData(data) {
      var aliases = data.aliases || [];
      var triggers = data.triggers || [];
      var p = Promise.resolve();

      out("Package includes:", MSG);
      out("Aliases: " + (aliases.length ? aliases.map(function (a) { return a.value || "(unnamed alias)"; }).join(", ") : "None"), MSG);
      out("Triggers: " + (triggers.length ? triggers.map(function (t) { return t.name || "(unnamed trigger)"; }).join(", ") : "None"), MSG);

      aliases.forEach(function (a) {
        p = p.then(function () {
          return installAlias(a);
        });
      });

      triggers.forEach(function (t) {
        p = p.then(function () {
          return installTrigger(t);
        });
      });

      p.then(function () {
        try { $("#closesettings").click(); } catch (e) {}
        out("Install complete.", OK);
      }).catch(function (e) {
        out("Install stopped: " + e.message, ERR);
      });
    }

    function installPackage() {
      var input = document.createElement("input");
      input.type = "file";
      input.accept = "application/json,.json";

      input.addEventListener("change", function () {
        var file = input.files && input.files[0];
        if (!file) return;

        out("Reading package: " + file.name, MSG);

        readPackage(file)
          .then(installData)
          .catch(function (e) {
            out("Could not read package: " + e.message, ERR);
          });
      });

      input.click();
    }

    function help() {
      out(VERSION, MSG);
      out("package create  - create a real package from Genesis aliases.json/triggers.json", MSG);
      out("package install  - install a selected package JSON", MSG);
      out("package debug    - show detected character/token/source URLs", MSG);
      out("package help     - show this help", MSG);
    }

    var command = getArgText().toLowerCase();

    if (!command || command === "help") {
      help();
      return;
    }

    if (command === "create") {
      createPackage();
      return;
    }

    if (command === "install" || command === "download") {
      installPackage();
      return;
    }

    if (command === "debug") {
      debug();
      return;
    }

    out("Unknown command: " + command, ERR);
    help();
  })();
} catch (e) {
  try {
    gwc.output.append("[Package ERROR] " + e.name + ": " + e.message, "#ff6666");
  } catch (ignore) {}
}

/*
AUTHOR: feskslo
Contains: 1 alias, 1 trigger

Automatically re-mounts your horse after it's left behind. Written for Bree horses.

USAGE: 
remount - Toggle automounting flag
remount <adj1> <adj2> - Enable automounting and set horse adjectives

1. ALIAS: remount
Execute the following javascript:
*/

// Handle case where no arguments are provided (toggle mode)
if (!args[1]) {
    gwc.userdata.autoMount = !gwc.userdata.autoMount;
    let status = gwc.userdata.autoMount ? "ON" : "OFF";

    gwc.output.append(`Automount is now: ${status}`, '#ffffff');
    gwc.output.append("Change your horse adjectives with: automount <adj1> <adj2>", '#ffffff');
    gwc.output.append("Your horse is: " + (gwc.userdata.myHorse || "not set."), '#ffffff');
    return;
}

// Handle case where too many arguments are provided
if (args[3]) {
    gwc.output.append("Error: Too many arguments. Usage: automount <adj1> <adj2>", '#ffffff');
    return;
}

// 2 arguments provided, store the two provided adjectives and set flag
gwc.userdata.myHorse = args['*'] + " horse";
gwc.userdata.autoMount = true;
gwc.output.append("Your horse is now: " + gwc.userdata.myHorse + ". Automount enabled.", '#ffffff');

/*
2. TRIGGER
Name: Utility - Auto Mount
Type: regexp
Pattern: ^(?!You are riding )(?!You start leading )(A|An|a |and a ) .+?(?!.* with you riding on )(?!.* comes galloping in) horse\b

Execute the following javascript:
*/
let match = args[0];

// Trim the matched text to only include "adj1 adj2 horse"
let words = match.split(/\s+/); 
let lastThreeWords = words.slice(-3).join(" "); 

if (lastThreeWords === gwc.userdata.myHorse) {
  if (gwc.userdata.autoMount) {
    gwc.connection.send("!mount horse");
  }
}

/*
Auto Restore V3.1
Trigger Name: Auto Restore
Trigger Pattern: ^(?!/\*|var |if |try |function |const |let ).+
Script Type: JavaScript Trigger

Required Alias(s):
- quest
- quest show
- ginv
- gloot

Required Trigger(s):
- none

Optional Alias(s)/Trigger(s):
- debug

Commands:
- none
*/

try {
  (function () {
    if (window.GenesisAutoRestoreStarted === true) {
      return;
    }

    window.GenesisAutoRestoreStarted = true;

    function debug(msg) {
      try {
        if (
          window.GenesisDebug &&
          typeof GenesisDebug.enabled === "function" &&
          GenesisDebug.enabled("restore") &&
          typeof GenesisDebug.log === "function"
        ) {
          GenesisDebug.log("restore", String(msg));
        }
      } catch (e) {}
    }

    function sendClientCommand(cmd) {
      try {
        if (gwc && gwc.connection && typeof gwc.connection.send === "function") {
          gwc.connection.send(cmd, true);
          return true;
        }
      } catch (e1) {
        debug(cmd + " send true failed: " + e1.message);
      }

      try {
        if (gwc && gwc.connection && typeof gwc.connection.send === "function") {
          gwc.connection.send(cmd);
          return true;
        }
      } catch (e2) {
        debug(cmd + " send failed: " + e2.message);
      }

      return false;
    }

    function restore(cmd, delayMs) {
      setTimeout(function () {
        try {
          debug("restore: " + cmd);
          sendClientCommand(cmd);
        } catch (e) {
          try {
            gwc.output.append(
              "[Auto Restore ERROR] " + cmd + " failed: " + e.name + ": " + e.message,
              "#ff6666"
            );
          } catch (ignore) {}
        }
      }, delayMs);
    }

    /*
      Current package restore only.
      Runs once per browser page load.
      No loops. No page scanning. No game inventory command.
    */

    restore("quest", 2200);
    restore("quest show", 3400);
    restore("ginv", 4600);
    restore("gloot on", 6000);

    setTimeout(function () {
      debug("restore queued");
    }, 6500);
  })();
} catch (e) {
  try {
    gwc.output.append("[Auto Restore ERROR] " + e.name + ": " + e.message, "#ff6666");
  } catch (ignore) {}
}

