      window.GenesisImbueCapture = window.GenesisImbueCapture || {
        active: false,
        counts: {
          unusual: 0,
          peculiar: 0,
          exotic: 0
        }
      };

      return window.GenesisImbueCapture;
    }

    function addBlock(counts) {
      if (window.GenesisImbueTracker && typeof window.GenesisImbueTracker.addBlock === "function") {
        window.GenesisImbueTracker.addBlock(counts);
        return;
      }

      /*
        If the alias has not been run yet, create minimal storage so counts are not lost.
      */
      gwc.userdata.imbue = gwc.userdata.imbue || {};
      gwc.userdata.imbue.session = gwc.userdata.imbue.session || {
        unusual: 0,
        peculiar: 0,
        exotic: 0,
        total: 0
      };

      gwc.userdata.imbue.session.unusual += Number(counts.unusual || 0);
      gwc.userdata.imbue.session.peculiar += Number(counts.peculiar || 0);
      gwc.userdata.imbue.session.exotic += Number(counts.exotic || 0);
      gwc.userdata.imbue.session.total += Number(counts.unusual || 0) + Number(counts.peculiar || 0) + Number(counts.exotic || 0);
